<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller;use App\Http\Requests\Api\RecipeRequest;use App\Http\Resources\RecipeResource;use App\Models\TnRecipeTemplate;use App\Repositories\RecipeRepository;use App\Services\CrudService;use Illuminate\Support\Facades\DB;
class RecipeController extends Controller {private CrudService $service;public function __construct(RecipeRepository $r){$this->service=new CrudService($r);}public function index(){return RecipeResource::collection($this->service->all(['steps']));}public function store(RecipeRequest $r){$recipe=DB::transaction(function()use($r){$d=$r->safe()->except('steps')+['created_by'=>$r->user()->id,'updated_by'=>$r->user()->id,'step_count'=>count($r->input('steps',[])),'time_unit'=>'MM.SS'];$x=$this->service->create($d);$x->steps()->createMany($this->steps($r->input('steps',[])));return $x;});return (new RecipeResource($recipe->load('steps')))->response()->setStatusCode(201);}public function show(TnRecipeTemplate $recipe){return new RecipeResource($recipe->load('steps'));}public function update(RecipeRequest $r,TnRecipeTemplate $recipe){DB::transaction(function()use($r,$recipe){$this->service->update($recipe,$r->safe()->except('steps')+['updated_by'=>$r->user()->id]);if($r->has('steps')){$recipe->steps()->delete();$recipe->steps()->createMany($this->steps($r->input('steps')));}});return new RecipeResource($recipe->fresh('steps'));}public function destroy(TnRecipeTemplate $recipe){$this->service->delete($recipe);return response()->noContent();}private function steps(array $s):array{return array_map(fn($x,$i)=>['step_number'=>$i+1,'step_name'=>$x['step_name']??'Step '.($i+1),'target_sv'=>$x['target_temperature']??$x['target_sv']??0,'target_pressure'=>$x['target_pressure']??null,'duration'=>$x['holding_time']??$x['duration']??0,'steam_enable'=>$x['steam_enable']??false,'cooling_enable'=>$x['cooling_enable']??false,'drain_enable'=>$x['drain_enable']??false,'alarm_enable'=>$x['alarm_enable']??true],$s,array_keys($s));}}
